def csvout(path,rows):
 if not rows:return
 fields=[]
 for r in rows:
  for k in r:
   if k not in fields:fields.append(k)
 with path.open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader()
  for r in rows:w.writerow({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(list,dict)) else v for k,v in r.items()})
def refused(answer):return any(x in answer for x in ['无法确认','资料不足','证据不足','无法回答','无法给出','没有关于','不足以','当前资料'])
def stage(primary,gate,track,sid):
 if primary in {'CITATION_MISSING','CITATION_INCOMPLETE','CITATION_MISMATCH'}:return 'C'
 if primary in {'INCOMPLETE','UNSUPPORTED_ADDITION','EVIDENCE_MISUSE','OVER_GENERALIZATION','WRONG_REFUSAL','FAILED_REFUSAL','TASK_COMPLETION'}:return 'G'
 if primary=='NO_GENERATION_FAILURE' and gate in {'EVIDENCE_PARTIAL','EVIDENCE_INSUFFICIENT'}:
  return 'NONE' if (track,sid)==('B','N02') else 'E'
 return 'NONE'
