def adjud_citation(rs):return dict(Counter(r['adjudicated_citation_assessment'] for r in rs))
def make_reports(m,comp,gate,reviewed,clean):
 disp=m['set_b_adjudicated_17']['proxy_disposition'];changed=[r for r in gate if r['changed']];tax=Counter(r['evidence_error_taxonomy'] for r in changed)
 (ROOT/'analysis/proxy_false_positive_analysis.md').write_text(f"# Proxy false positive analysis\n\nSECONDARY_AI_ADJUDICATION only; not human validation. Confirmed: {disp.get('CONFIRMED',0)}; partially confirmed: {disp.get('PARTIALLY_CONFIRMED',0)}; false positive: {disp.get('FALSE_POSITIVE',0)}; reassigned: {disp.get('REASSIGN_FAILURE',0)}.\n\nTASK_COMPLETION over-triggered on correct/appropriately refusing answers; UNSUPPORTED_ADDITION had conservative lexical false positives; WRONG_REFUSAL ignored partial evidence; EVIDENCE_SUFFICIENT often accepted topic-related but non-answering material.\n",encoding='utf-8')
 (ROOT/'analysis/evidence_sufficiency_failure_taxonomy.md').write_text('# Evidence sufficiency failure taxonomy\n\n'+'\n'.join(f'- {k}: {v}' for k,v in tax.most_common())+'\n\nChanged cases are listed in `results/evidence_gate_reconciliation.csv`; categories summarize adjudication rationales without changing them.\n',encoding='utf-8')
 c=comp['metrics'];(ROOT/'analysis/original_vs_reconciled_analysis.md').write_text('# Original vs reconciled\n\n| Metric | Original V0 | Reconciled V0.1 | Delta |\n|---|---:|---:|---:|\n'+'\n'.join(f"| {k} | {v['original']} | {v['reconciled']} | {v.get('delta','NOT_DIRECTLY_COMPARABLE')} |" for k,v in c.items())+'\n\nThe reconciled set is HYBRID_RECONCILED: 17 secondary-AI rows plus 33 unreviewed original proxies. Completeness, unsupported-claim rate and citation coverage use incompatible denominators and are not forced into numeric deltas.\n',encoding='utf-8')
 s=m['set_c_hybrid_reconciled_50'];(ROOT/'analysis/reconciled_generation_analysis.md').write_text(f"# Reconciled generation analysis\n\nReconciled clean subset: {s['clean_subset_size']}. Correctness: {s['clean_correctness_mean_0_to_2']}/2 ({s['clean_correctness_normalized']:.2%}). Faithfulness retained proxy: {s['clean_faithfulness_mean_0_to_2_retained_proxy']}/2; adjudication coverage 0%, so it is not a reconciled semantic score. Reviewed completeness: {m['set_b_adjudicated_17']['completeness_distribution']}. Reviewed unsupported answers: {m['set_b_adjudicated_17']['unsupported_answer_distribution']}.\n",encoding='utf-8')
 (ROOT/'analysis/bottleneck_reassessment.md').write_text(f"# Bottleneck reassessment\n\nEvidence-sufficient count fell from {m['set_a_original_v0']['evidence_gate_distribution'].get('EVIDENCE_SUFFICIENT',0)} to {s['evidence_gate_distribution'].get('EVIDENCE_SUFFICIENT',0)}; clean subset fell from {m['set_a_original_v0']['clean_subset_size']} to {s['clean_subset_size']}. Nine reviewed cases were downgraded. Reconciled clean correctness is {s['clean_correctness_normalized']:.2%}, so Generation remains materially weak after gate correction.\n\nEvidence Sufficiency is now the first bottleneck because the review found systematic gate false positives (topic-related, partial, wrong-document and concept-mismatch evidence). Generation is the second independent bottleneck; Citation coverage is third.\n\n## Next step\n\nProceed first with **Evidence Sufficiency V0.1**. After its gate is frozen and revalidated, proceed to Generation V0.1, then citation coverage. No optimization is performed in this experiment.\n",encoding='utf-8')
